    y = points.length ? Math.min(...points.map((p) => p.y)) : 0;
  const bounds = {
    x,
    y,
    width: points.length ? Math.max(...points.map((p) => p.x)) - x : 0,
    height: points.length ? Math.max(...points.map((p) => p.y)) - y : 0,
